package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeMultiply(double[] v)
 */
public class OpenMapRealVector_ebeMultiply_TriageGen1Test {

    @Test
    public void testEbeMultiply_Success() {
        // Setup a sparse vector: dimension 5, entries at index 1 and 3
        OpenMapRealVector vector = new OpenMapRealVector(5);
        vector.setEntry(1, 2.0);
        vector.setEntry(3, 4.0);

        // Multiplier array
        double[] v = {1.0, 5.0, 1.0, 0.5, 1.0};

        // Expected result:
        // index 1: 2.0 * 5.0 = 10.0
        // index 3: 4.0 * 0.5 = 2.0
        // others remain 0.0 (not stored in sparse map)
        OpenMapRealVector result = vector.ebeMultiply(v);

        Assert.assertEquals("Dimension should match", vector.getDimension(), result.getDimension());
        Assert.assertEquals("Entry at index 1 failed", 10.0, result.getEntry(1), 1e-10);
        Assert.assertEquals("Entry at index 3 failed", 2.0, result.getEntry(3), 1e-10);
        Assert.assertEquals("Entry at index 0 should be 0", 0.0, result.getEntry(0), 1e-10);
        Assert.assertEquals("Entry at index 2 should be 0", 0.0, result.getEntry(2), 1e-10);
        Assert.assertEquals("Entry at index 4 should be 0", 0.0, result.getEntry(4), 1e-10);
    }

    @Test
    public void testEbeMultiply_ZeroMultiplier() {
        OpenMapRealVector vector = new OpenMapRealVector(3);
        vector.setEntry(0, 10.0);
        vector.setEntry(2, 20.0);

        double[] v = {0.0, 1.0, 0.0};

        OpenMapRealVector result = vector.ebeMultiply(v);

        // result.setEntry(0, 10.0 * 0.0) -> index 0 becomes 0.0
        // result.setEntry(2, 20.0 * 0.0) -> index 2 becomes 0.0
        Assert.assertEquals(0.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(2), 1e-10);
    }

    @Test
    public void testEbeMultiply_EmptySparseVector() {
        // Vector with no entries (all zeros)
        OpenMapRealVector vector = new OpenMapRealVector(10);
        double[] v = new double[10];
        for (int i = 0; i < 10; i++) v[i] = i + 1.0;

        OpenMapRealVector result = vector.ebeMultiply(v);

        Assert.assertEquals(10, result.getDimension());
        // Since vector was empty, the iterator loop should not execute, result stays empty
        Assert.assertEquals(0.0, result.getL1Distance(new OpenMapRealVector(10)), 1e-10);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeMultiply_DimensionMismatch() {
        OpenMapRealVector vector = new OpenMapRealVector(5);
        vector.setEntry(1, 1.0);

        // Array length 3 is not equal to vector dimension 5
        double[] v = {1.0, 2.0, 3.0};

        vector.ebeMultiply(v);
    }

    @Test
    public void testEbeMultiply_LargeValues() {
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.setEntry(0, Double.MAX_VALUE);

        double[] v = {2.0, 1.0};

        OpenMapRealVector result = vector.ebeMultiply(v);
        Assert.assertTrue("Should result in Infinity", Double.isInfinite(result.getEntry(0)));
    }

    @Test
    public void testEbeMultiply_Immutability() {
        // Ensure the original vector is not modified
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.setEntry(0, 5.0);
        double[] v = {2.0, 2.0};

        OpenMapRealVector result = vector.ebeMultiply(v);

        Assert.assertEquals("Original vector must remain unchanged", 5.0, vector.getEntry(0), 1e-10);
        Assert.assertEquals("Result should be modified", 10.0, result.getEntry(0), 1e-10);
    }
}
